{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_dist = case["core_distance"]
    distances = case["distances"]

    # Compute mutual reachability distances for all pairs
    mrd_edges = []
    for u, v, d in distances:
        mrd = max(core_dist[u], core_dist[v], d)
        mrd_edges.append((mrd, u, v))

    # Sort edges by mutual reachability distance (Kruskal's)
    mrd_edges.sort()

    # Union-Find data structure
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            rx, ry = ry, rx
        parent[ry] = rx
        if rank[rx] == rank[ry]:
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    target = len(nodes) - 1

    for mrd, u, v in mrd_edges:
        if union(u, v):
            mst_edges.append([u, v, mrd])
            total_weight += mrd
            if len(mst_edges) == target:
                break

    return {"mst_edges": mst_edges, "total_weight": total_weight}
"}
